const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const R=path.resolve(__dirname,'..'),main=path.resolve(process.env.ATOMIC_RULES_REPO||path.resolve(R,'../../..')),read=n=>fs.readFileSync(path.join(R,n),'utf8');
const A='总打码倍数1.3720(有效投注137.2/总充值100)小于配置4',B='累计提款次数0小于配置1次',C='首存金额5000大于等于配置4999';
async function wg(){let run;const source=fs.readFileSync(path.join(main,'tests/wg-withdraw-blocking-canonical-groups.test.cjs'),'utf8');const req=x=>x==='node:test'?{test:()=>{},before:f=>run=f,after:()=>{}}:require(x);const api=new Function('require','__dirname',source+';return {get:()=>db,call,seed,manual,checksum};')(req,path.join(main,'tests'));await run();const db=api.get();await db.exec('delete from public.wg_withdraw_details;delete from private.wg_verified_front_rejection_notes;');for(const n of ['dashboard_admin_live_blocking_core','dashboard_admin_live_blocking_details_cleaned','dashboard_admin_live_blocking_members','dashboard_admin_wg_withdraw_reasons'])await db.exec(read('sql/'+n+'.sql'));return {...api,db};}
test('WG shared atomic membership preserves all source flags and exact rejection path',async()=>{const {db,call,seed,manual,checksum}=await wg();try{for(const [i,n,status]of [[1,`${A};${B}`,4],[2,`${A};${C}`,7],[3,B,2],[4,`${A};${A};${B}`,4]])await seed('ATOM-'+i,manual(n,{rejection_reason:'EXACT REJECTION'}),status);await seed('AUTO',manual(A,{operator_class:'auto',operator_name:'system'}));await seed('UNKNOWN',manual(A,{operator_class:'unknown',operator_name:null}));await seed('EMPTY',manual(null,{note_state:'empty'}),7);await seed('MISSING',manual(null,{note_state:undefined,front_note_state:undefined,back_note_state:undefined}),7);const before=await checksum();const d=await call();assert.equal(d.reasonGrouping,'atomic_rules_v1');assert.equal(d.noteCount,6);assert.equal(d.summary.operatorCounts.manual,6);assert.equal(d.summary.selectedCount,6);assert.equal(d.summary.ruleMembership.hitCount,9);const a=d.rows.find(r=>r.reason==='总打码倍数小于配置倍数');assert.equal(a.count,3);const orders=await call({kind:'blockingOrders',reasonKey:a.reasonKey});assert.equal(orders.total,3);assert(orders.rows.every(r=>r.blockingActualValue==='1.3720'));assert.equal((await call({kind:'rejection'})).rows.find(r=>r.reason==='EXACT REJECTION').count,1);assert.equal(await checksum(),before);assert.equal(d.coverage.complete,true);}finally{await db.close();}});
